package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_siblingElements_TriageGen0Test {

    @Test
    public void testSiblingElementsWithMultipleChildren() {
        String html = "<html><body><div id='parent'><p>1</p><span>2</span><p>3</p></div></body></html>";
        Document doc = Parser.parse(html);
        Element parent = doc.selectFirst("#parent");
        Element firstChild = parent.child(0);

        Elements siblings = firstChild.siblingElements();

        // siblingElements() returns parent().children()
        // In Jsoup, children() returns all children of the parent, including the element itself.
        Assert.assertEquals(3, siblings.size());
        Assert.assertEquals("p", siblings.get(0).tagName());
        Assert.assertEquals("span", siblings.get(1).tagName());
        Assert.assertEquals("p", siblings.get(2).tagName());
        Assert.assertTrue(siblings.contains(firstChild));
    }

    @Test
    public void testSiblingElementsWithSingleChild() {
        String html = "<html><body><div id='parent'><p>1</p></div></body></html>";
        Document doc = Parser.parse(html);
        Element parent = doc.selectFirst("#parent");
        Element child = parent.child(0);

        Elements siblings = child.siblingElements();

        Assert.assertEquals(1, siblings.size());
        Assert.assertEquals(child, siblings.get(0));
    }

    @Test
    public void testSiblingElementsWithNoChildren() {
        // This case is technically impossible for a valid Element instance to call siblingElements() 
        // if it has no parent, but we test the logic via a detached element.
        Element detached = new Element(new org.jsoup.parser.Tag("div"), "");

        // parent() will return null for a detached element
        try {
            detached.siblingElements();
            Assert.fail("Should have thrown NullPointerException because parent() is null");
        } catch (NullPointerException e) {
            // Expected behavior: parent() returns null, calling .children() on null throws NPE
        }
    }

    @Test
    public void testSiblingElementsEmptyParent() {
        String html = "<html><body><div id='parent'></div></body></html>";
        Document doc = Parser.parse(html);
        Element parent = doc.selectFirst("#parent");

        // We can't easily call siblingElements() on a non-existent child, 
        // but we can verify the relationship.
        Assert.assertEquals(0, parent.children().size());
    }

    @Test
    public void testSiblingElementsIdentity() {
        String html = "<div><p></p></div>";
        Document doc = Parser.parse(html);
        Element parent = doc.body().parent(); // The div
        Element child = parent.child(0);

        Elements siblings = child.siblingElements();
        Elements parentChildren = parent.children();

        // siblingElements() is defined as parent().children()
        Assert.assertEquals(parentChildren, siblings);
    }
}
